using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ClearingRewardsList", menuName = "Data/Rewards/ClearingRewards List")]
public class ClearingRewardsList : ScriptableObject
{
	[SerializeField]
	private List<ClearingReward> clearingRewards = new List<ClearingReward>();

	public List<ClearingReward> ClearingRewards => clearingRewards;

	public ClearingReward GetClearingReward(string clearingRewardName)
	{
		string text = clearingRewardName.Replace(" ", "").ToLower();
		for (int i = 0; i < clearingRewards.Count; i++)
		{
			if (text == clearingRewards[i].name.ToLower())
			{
				return clearingRewards[i];
			}
		}
		return null;
	}
}
